vectors.spec:
name "ex"
bin "ex"
flag "--bin-names" env="EX_BIN" {
  default_if "--json" "true"
}
flag "--json"

name "ex"
bin "ex"
flag "--bin-names" {
  default_if "--json" "true"
}
flag "--json" env="EX_JSON"

name "ex"
bin "ex"
flag "--style <s>" default="plain" {
  default_if "--json" "compact"
}
flag "--json"

name "ex"
bin "ex"
flag "--pretty" {
  default_if "--json" "false" "true"
}
flag "--json" negate="--no-json"
